import re as _re

def _t():

    def f():
        raise StopIteration

    def g():
        yield f()
    try:
        next(g())
    except RuntimeError as _exc:
        assert _re.search('generator raised StopIteration', str(_exc)), 'assertRaisesRegex: message mismatch'
    else:
        raise AssertionError('assertRaises: did not raise')
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

def _t():

    def f():
        raise StopIteration

    def g():
        yield f()
    try:
        next(g())
    except RuntimeError as exc:
        assert type(exc.__cause__) is StopIteration, ('assertIs', type(exc.__cause__), StopIteration)
        assert type(exc.__context__) is StopIteration, ('assertIs', type(exc.__context__), StopIteration)
        assert exc.__suppress_context__, ('assertTrue', exc.__suppress_context__)
    else:
        raise AssertionError('__cause__, __context__, or __suppress_context__ were not properly set')
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')
